def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if divider is None:
        return [row[:] for row in grid]
    out = [[2 if v == 2 else 0 for v in row] for row in grid]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 4:
                if r < divider:
                    nr = r + 1
                    out[nr][c] = 4
                    if nr == divider - 1:
                        for dc in (-1, 1):
                            rr, cc = nr - 1, c + dc
                            while 0 <= rr < h and 0 <= cc < w:
                                out[rr][cc] = 4
                                rr -= 1
                                cc += dc
                elif r > divider:
                    out[min(h - 1, r + 1)][c] = 4
    return out
